patch:
diff --git a/src/server.js b/src/server.js
index 0969320..3bfd7d0 100644
--- a/src/server.js
+++ b/src/server.js
@@ -1,7 +1,7 @@
 import http from 'node:http'
 import { Router } from './router.js'
 import { Inventory } from './inventory.js'
-import { Cart } from './cart.js'
+import { Cart, DISCOUNT_CODES } from './cart.js'
 import { formatCurrency } from './format.js'

 /**
@@ -22,9 +22,33 @@ export function createApp(inventory = Inventory.fromFile()) {
   })

   router.post('/cart/quote', ({ body }) => {
+    // validate items
+    if (!body.items || !Array.isArray(body.items) || body.items.length === 0) {
+      return { status: 400, body: { error: 'items must be a non-empty array' } }
+    }
+
+    // validate each item and build the cart
     const cart = new Cart(inventory)
-    for (const item of body.items) cart.addItem(item.id, item.quantity)
-    if (body.discountCode) cart.applyDiscount(body.discountCode)
+    for (const item of body.items) {
+      if (!item || typeof item.id !== 'string') {
+        return { status: 400, body: { error: 'each item must have an id string' } }
+      }
+      const book = inventory.find(item.id)
+      if (!book) return { status: 400, body: { error: `Unknown book: ${item.id}` } }
+      const qty = item.quantity ?? 1
+      if (!Number.isInteger(qty) || qty <= 0) {
+        return { status: 400, body: { error: `Invalid quantity for ${item.id}: ${qty}` } }
+      }
+      cart.addItem(item.id, qty)
+    }
+
+    if (body.discountCode) {
+      if (!DISCOUNT_CODES[body.discountCode]) {
+        return { status: 400, body: { error: `Invalid discount code: ${body.discountCode}` } }
+      }
+      cart.applyDiscount(body.discountCode)
+    }
+
     const total = cart.total()
     return { status: 200, body: { totalCents: total, total: formatCurrency(total) } }
   })
